arguments.command:
python3 -c "
import zipfile
with zipfile.ZipFile('project_proposal_template.hwpx','r') as z:
    for n in z.namelist():
        try:
            data = z.read(n).decode('utf-8','ignore')
            if '{{' in data:
                print(f'=== {n} ===')
                import re
                for m in re.finditer(r'\{\{', data):
                    start = max(0, m.start()-80)
                    end = min(len(data), m.end()+120)
                    print(repr(data[start:end]))
                    print()
        except: pass
"

